/**
 * engine-server/pipeline/template-update-checker.ts — 模板版本管理 + 更新检测
 *
 * V1.2 发布配套：为 FE-33 版本更新推送功能提供引擎侧数据。
 *
 * 逻辑：
 * 1. 读取模板库中所有模板的 manifest.json
 * 2. 对比用户已安装模板版本
 * 3. 返回有更新的模板列表
 *
 * @packageDocumentation
 */
export interface TemplateManifest {
    schemaVersion: string;
    id: string;
    name: string;
    version: string;
    description: string;
    category: string;
    tags: string[];
    icon: string;
    quality: string;
    engineVersion: string;
    distilledBy: string;
    distillDate: string;
    distillNotes?: string;
    agents: Array<{
        name: string;
        role: string;
        description: string;
        suggestedModel: string;
    }>;
    firstTaskPrompt?: string;
    teamWorkflow?: string;
    requiredSkills?: string[];
}
export interface TemplateUpdateInfo {
    /** 模板 ID */
    templateId: string;
    /** 模板名称 */
    templateName: string;
    /** 最新版本 */
    latestVersion: string;
    /** 用户已安装版本（null = 未安装） */
    installedVersion: string | null;
    /** 是否有更新 */
    hasUpdate: boolean;
    /** 更新内容 */
    changelog: string[];
    /** 是否为新增模板（之前未安装） */
    isNew: boolean;
}
export interface TemplateUpdateCheckResult {
    /** 全部模板最新版本列表 */
    allTemplates: TemplateUpdateInfo[];
    /** 有更新的模板 */
    updates: TemplateUpdateInfo[];
    /** 新增模板 */
    newTemplates: TemplateUpdateInfo[];
    /** 模板总数 */
    totalCount: number;
    /** 更新时间戳 */
    checkedAt: string;
}
/**
 * 加载旗舰模板目录下的所有模板
 */
export declare function loadAllTemplates(): Map<string, TemplateManifest>;
/**
 * 对比已安装模板和最新模板，返回更新信息。
 *
 * @param installedVersions - 用户已安装模板版本映射 { templateId: version }
 * @returns 更新检测结果
 */
export declare function checkTemplateUpdates(installedVersions?: Record<string, string>): TemplateUpdateCheckResult;
/**
 * 获取引擎当前版本（兼容墨翟 /api/update/check API）
 */
export declare function getEngineUpdateInfo(): {
    currentVersion: string;
    releaseDate: string;
    changelog: string[];
};
